  ReleaseNote('0.9.21', [
    NoteItem('یک سرور پایش برای همهٔ مدارس: هر مدرسه‌ای که در پنل مالک تعریف می‌شود (مثل «دبستان آزادی (2)») بی‌هیچ کاری روی همان رایانهٔ سرور، سرور خودش را می‌گیرد — دادهٔ جدا (پوشهٔ hosted/<مدرسه> و بخش جدا در دیتابیس) و همان نشانی شبکه/تونل. پنل مالک برای همهٔ مدارس «سرور وصل» نشان می‌دهد و مدیر مدرسهٔ تازه با نام کاربری و رمزی که مالک داده از همان نشانی وارد می‌شود؛ هر کاربر خودکار به سرور مدرسهٔ خودش می‌رسد.'),
    NoteItem('اشتراک بدون گیر: در پنل مالک می‌توان هر دو گزینهٔ ماهانه و سالانهٔ یک نقش را برداشت یا مبلغ را خالی/صفر گذاشت؛ چنین نقشی رایگان است («بدون گزینهٔ پولی — این نقش رایگان است») و کاربرانش پشت دیوار اشتراک نمی‌مانند.'),
    NoteItem('دورهٔ آزمایشی: وقتی مالک آزمایشی را روشن کرده، کاربری که نقشش اشتراک لازم دارد و هنوز اشتراکی نداشته، با ورود به برنامه خودکار همان دوره را می‌گیرد (یک بار برای هر کاربر و هر دستگاه) و بی‌درنگ از برنامه استفاده می‌کند.'),
  ]),
];
